from flask import Flask, request, render_template_string, make_response

app = Flask(__name__)

RAW_CONTENT_TAGS = {"style", "script", "iframe", "noembed", "noscript", "noframes", "xmp", "plaintext"}

def escape_html(s):
    return s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")

def escape_attr(s):
    return escape_html(s).replace('"', "&quot;")

def serialize_node(tag, attrs, children):
    out = "<" + tag
    for k, v in attrs.items():
        out += ' ' + k + '="' + escape_attr(v) + '"'
    out += ">"
    inner = "".join(children)
    # raw-content elements are emitted verbatim except for a partial fix:
    # only the exact closing tag of the parent is escaped (case-insensitive)
    if tag in RAW_CONTENT_TAGS:
        closing = "</" + tag
        if closing.lower() in inner.lower():
            import re
            inner = re.sub(re.escape(closing), lambda m: "&lt;" + m.group(0)[1:], inner, flags=re.IGNORECASE)
        out += inner
    else:
        out += escape_html(inner)
    out += "</" + tag + ">"
    return out

@app.route("/render")
def render_page():
    # source: user-controlled markup fragments
    user_tag = request.args.get("tag", "div")
    user_content = request.args.get("content", "")
    style_body = request.args.get("style", "")
    node = serialize_node(user_tag, {}, [user_content])
    style_node = serialize_node("style", {}, [style_body])
    html = "<html><body>" + node + style_node + "</body></html>"
    resp = make_response(render_template_string(html))
    resp.headers["Content-Type"] = "text/html"
    return resp

if __name__ == "__main__":
    app.run()
