const express = require('express');
const crypto = require('crypto');
const jwt = require('jsonwebtoken');

const app = express();

// Weak encryption: AES-128-ECB with a hardcoded key, mirroring the original EncryptUtils.decrypt
function decryptToken(encrypted) {
  const key = Buffer.from('streampark-secret-key', 'utf8');
  const decipher = crypto.createDecipheriv('aes-128-ecb', key, null);
  return Buffer.concat([decipher.update(Buffer.from(encrypted, 'base64')), decipher.final()]).toString('utf8');
}

// Auth middleware chain: extract token from header, decrypt, verify JWT
function authMiddleware(req, res, next) {
  const token = req.get('Authorization');
  if (!token) {
    return res.status(401).json({ error: 'missing token' });
  }
  try {
    const decrypted = decryptToken(token);
    const payload = jwt.verify(decrypted, 'jwt-signing-secret');
    req.user = payload;
    next();
  } catch (err) {
    return res.status(401).json({ error: 'invalid token' });
  }
}

// CORS middleware reflecting Origin, same as original preHandle
app.use((req, res, next) => {
  res.setHeader('Access-Control-Allow-Origin', req.get('Origin') || '*');
  res.setHeader('Access-Control-Allow-Methods', 'GET,POST,OPTIONS,PUT,DELETE');
  res.setHeader('Access-Control-Allow-Headers', req.get('Access-Control-Request-Headers') || '');
  if (req.method === 'OPTIONS') {
    return res.sendStatus(200);
  }
  next();
});

app.use(authMiddleware);

app.get('/api/tasks', (req, res) => {
  res.json({ tasks: [], user: req.user });
});

app.listen(8080);
