  '/metrics':  { cmd: 'cat /etc/hostname', script: 'return 3;' }
});

const ALLOWED_HOSTS = Object.freeze(['127.0.0.1']);
const LOG_PATH = '/var/log/route-guard.log';

function validateRoute(route) {
  return Object.prototype.hasOwnProperty.call(ROUTE_TABLE, route);
}

function runHealthCheck() {
  const { execSync } = require('child_process');
  // 危险点1: execSync — 实参为 ROUTE_TABLE['/health'].cmd 字面量常量
  const out = execSync(ROUTE_TABLE['/health'].cmd, { timeout: 3000 });
  return out.toString().trim();
}

function runScriptCheck() {
  // 危险点2: eval — 实参为字面量字符串常量
  return eval('2 + 3');
}

function openLog() {
  const fs = require('fs');
  // 危险点3: open — 实参为常量 LOG_PATH 与固定 flag
  return fs.openSync(LOG_PATH, 'r');
}

module.exports = { validateRoute, runHealthCheck, runScriptCheck, openLog };
